import{_ as a,C as i,o as n,c as s,ag as t,E as d}from"./chunks/framework.Drp2S_UI.js";const b=JSON.parse('{"title":"Deploy documentation to GitHub Pages","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/docs-deployment.md","filePath":"en/guide/docs-deployment.md","lastUpdated":1792653875000}'),r={name:"en/guide/docs-deployment.md"};function l(c,e,h,p,u,g){const o=i("MermaidDiagram");return n(),s("div",null,[e[0]||(e[0]=t('<h1 id="deploy-documentation-to-github-pages" tabindex="-1">Deploy documentation to GitHub Pages <a class="header-anchor" href="#deploy-documentation-to-github-pages" aria-label="Permalink to &quot;Deploy documentation to GitHub Pages&quot;">​</a></h1><p>VitePress sources live in <code>docs/</code>. Merging into <code>main</code> triggers <code>.github/workflows/docs.yml</code>, builds the documentation and online editor demo, updates <code>gh-pages</code>, and deploys the same artifact through official Pages Actions. The workflow still needs repository Pages configuration and a successful remote run before the site is available.</p><h2 id="one-time-setup" tabindex="-1">One-time setup <a class="header-anchor" href="#one-time-setup" aria-label="Permalink to &quot;One-time setup&quot;">​</a></h2><ol><li>Open <strong>Settings → Pages → Build and deployment</strong>.</li><li>Set <strong>Source</strong> to <strong>GitHub Actions</strong>.</li><li>Enable Actions and allow the workflow&#39;s <code>GITHUB_TOKEN</code> to write <code>gh-pages</code>. The <code>github-pages</code> environment must allow deployments from <code>main</code>; organization policies and branch rules can restrict access.</li><li>Merge into <code>main</code>, or manually run <strong>Documentation Pages</strong> against <code>main</code>.</li><li>Open the deploy job&#39;s environment URL. With the current repository name, the expected project URL is <code>https://herberthe.github.io/canvas-editor/</code>; this is not a claim that it is already live.</li></ol><p>Do not select <strong>Deploy from a branch</strong> for this workflow. GitHub does not trigger branch-based Pages builds from commits pushed with <code>GITHUB_TOKEN</code>. Here <code>gh-pages</code> preserves inspectable static output, while <code>deploy-pages</code> publishes the artifact directly. See <a href="https://docs.github.com/en/pages/getting-started-with-github-pages/configuring-a-publishing-source-for-your-github-pages-site" target="_blank" rel="noreferrer">GitHub&#39;s publishing-source documentation</a>.</p><p>No SSH server credentials, HOST, USERNAME, PASSWORD, DOCS_PATH or PAT are needed. <code>configure-pages</code> checks an existing configuration; it does not automatically enable the site with the default token. Configure Pages first and rerun if that check fails.</p><h2 id="trigger-and-artifact-flow" tabindex="-1">Trigger and artifact flow <a class="header-anchor" href="#trigger-and-artifact-flow" aria-label="Permalink to &quot;Trigger and artifact flow&quot;">​</a></h2>',7)),d(o,{code:`flowchart TD
  PR[Documentation-related PR targeting main] --> Build[Frozen install, Mermaid validation, VitePress build]
  Main[Push main, including merges] --> Build
  Manual[Manual run on main] --> Build
  Build --> Gate{Main and not a PR?}
  Gate -->|No| Check[Build verification only]
  Gate -->|Yes| Artifact[Upload github-pages artifact]
  Artifact --> Branch[Extract the same artifact and update gh-pages]
  Branch --> Deploy[Official deploy-pages publishes the same artifact]
  Deploy --> Site[github-pages environment / documentation site]
`}),e[1]||(e[1]=t(`<table tabindex="0"><thead><tr><th>Job</th><th>Purpose</th><th>Write access</th></tr></thead><tbody><tr><td><code>build</code></td><td>Node 24, pnpm 10.32.1, frozen install, diagrams and VitePress build</td><td>None; contents read only</td></tr><tr><td><code>publish-branch</code></td><td>Download artifact.tar and synchronize the extracted site root to gh-pages</td><td>contents write</td></tr><tr><td><code>deploy</code></td><td>Check Pages configuration and deploy the same artifact</td><td>pages write, id-token write</td></tr></tbody></table><p>Relevant PRs only validate. Every main push rebuilds, including source changes without Markdown changes. Manual runs on other branches build without publishing. Runs for the same ref are serialized; deployment uses the <code>github-pages</code> environment.</p><p>The output contains root <code>index.html</code>, <code>guide/</code>, <code>en/</code>, <code>assets/</code> and <code>.nojekyll</code>. Do not edit generated branch files directly. Change documentation sources in a development branch and merge into main. <code>clean: true</code> removes obsolete generated pages; the workflow does not force-push over branch history.</p><h2 id="local-validation-and-base-url" tabindex="-1">Local validation and base URL <a class="header-anchor" href="#local-validation-and-base-url" aria-label="Permalink to &quot;Local validation and base URL&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:preview</span></span></code></pre></div><p>Default base is <code>/canvas-editor/</code>; open that path on the preview server. Output is <code>docs/.vitepress/dist</code>, including the standalone editor and its workers, WASM, fonts and assets under <code>playground/</code>. The home page, navigation and <a href="./playground.html">playground guide</a> link to it. <code>docs:build</code> includes Mermaid syntax validation, so malformed diagrams fail CI. Chinese and English entry points are <code>/canvas-editor/</code> and <code>/canvas-editor/en/</code>. Search uses a local build-time index without Algolia credentials. Diagrams load on the client, follow the current theme and expose their source.</p><h2 id="repository-rename-and-custom-domains" tabindex="-1">Repository rename and custom domains <a class="header-anchor" href="#repository-rename-and-custom-domains" aria-label="Permalink to &quot;Repository rename and custom domains&quot;">​</a></h2><p>VitePress reads <code>DOCS_BASE</code>, defaulting to <code>/canvas-editor/</code>. If the repository is renamed, update the workflow&#39;s build environment to <code>/&lt;new-repository&gt;/</code> and validate locally with the same value.</p><p>For a custom domain or user root site, the base is usually <code>/</code>. Configure GitHub Pages DNS and Custom domain separately. If a CNAME file is needed, add the real domain to <code>docs/public/CNAME</code>; editing only the generated branch would lose it during clean publication. No domain or DNS configuration is performed by this change.</p><h2 id="demo-ci-and-troubleshooting" tabindex="-1">Demo CI and troubleshooting <a class="header-anchor" href="#demo-ci-and-troubleshooting" aria-label="Permalink to &quot;Demo CI and troubleshooting&quot;">​</a></h2><p><code>.github/workflows/build.yml</code> runs application lint, type checking, tests and demo build, then uploads <code>canvas-editor-demo</code>. The docs workflow separately builds the same demo into the site&#39;s <code>playground/</code> subdirectory without overwriting the documentation homepage or deploying to the upstream maintainer&#39;s server.</p><p>Both <code>docs:dev</code> and <code>docs:build</code> first run <code>scripts/build-docs-demo.mjs</code>, using DOCS_BASE for demo asset URLs. Generated output in <code>docs/public/playground/</code> is ignored by Git and copied into the final site by VitePress. Do not commit it. The demo inside the docs development server is a static build; restart <code>docs:dev</code> after editing editor sources.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>configure-pages fails</td><td>Set Pages Source to GitHub Actions, then rerun</td></tr><tr><td>gh-pages write returns 403</td><td>Actions policy, contents permission and gh-pages branch rules</td></tr><tr><td>Environment blocks deployment</td><td>github-pages allowed branches or required reviewers</td></tr><tr><td>Assets/subpages return 404</td><td>DOCS_BASE, repository name, full artifact and URL prefix</td></tr><tr><td>Workflow is missing</td><td>File merged into main and Actions enabled</td></tr><tr><td>PR has no deployment URL</td><td>Expected: deployment starts after merging into main</td></tr></tbody></table><p>Local validation cannot prove remote deployment success. Inspect all three jobs and the environment URL in the actual GitHub run.</p>`,14))])}const f=a(r,[["render",l]]);export{b as __pageData,f as default};
